/* repertoire — generated by node build.cjs */
(()=>{
const canonicalSong=(title,artist)=>[title,artist].map(value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')).join('-');
function queueSharedPractice(state,active,part){if(!state.sharingAccount||!part.seconds)return;if(active.socialAccount!==state.sharingAccount){active.socialAccount=state.sharingAccount;active.socialDates={};}active.socialDates??={};state.socialQueue??=[];let slot=active.socialDates[part.date];if(!slot||typeof slot==='string')slot=active.socialDates[part.date]={id:globalThis.crypto.randomUUID(),seconds:0};slot.seconds=Math.min(86400,slot.seconds+part.seconds);let record=state.socialQueue.find(r=>r.id===slot.id);if(!record){const song=state.songs.find(s=>s.id===active.songId);if(!song)return;record={id:slot.id,accountId:state.sharingAccount,date:part.date,songKey:canonicalSong(song.title,song.artist),title:song.title,artist:song.artist,seconds:slot.seconds};state.socialQueue.push(record);}else record.seconds=slot.seconds;}
function acknowledgeSharedRecords(state,sent){const values=new Map(sent.map(r=>[r.id,r.seconds]));state.socialQueue=(state.socialQueue||[]).filter(r=>!values.has(r.id)||r.seconds>values.get(r.id));}
function addSharedSet(state,set){const songs=[];for(const entry of set.songs){let song=state.songs.find(s=>canonicalSong(s.title,s.artist)===entry.song_key);if(!song){song={id:globalThis.crypto.randomUUID(),title:entry.title,artist:entry.artist,bpm:entry.bpm,minutes:entry.minutes,notes:'',lesson:'',sample:false};state.songs.push(song);}songs.push({songId:song.id,minutes:entry.minutes});}state.sharedPractice={id:set.id,name:set.name,songs};return songs;}

const DAYS=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const STARTER_LESSONS={'Blackbird':'https://www.youtube.com/watch?v=mEn2SEwZKNE','Dust in the Wind':'https://www.youtube.com/watch?v=tvwsFfmKw6A','Wish You Were Here':'https://www.youtube.com/watch?v=sG_K8sGflBY','Landslide':'https://www.youtube.com/watch?v=SERxZkTyQAg'};
const DEFAULT_SONGS=[
 ['Randall Collins','Norman Blake'],
 ['Seney Stretch','Billy Strings'],
 ["Debra's Waltz",'Billy Strings'],
 ['Dust In A Baggie','Billy Strings'],
 ['Turmoil and Tinfoil','Billy Strings'],
 ['Groundhog','Doc Watson'],
 ['Columbus Stockade Blues','Doc Watson'],
 ['Ready for the Times to Get Better','Doc Watson'],
 ['Hide and Seek','Billy Strings'],
 ['Little White Church','Billy Strings'],
 ['Whiskey Before Breakfast','Norman Blake'],
 ['Summertime','Doc Watson'],
 ['Pretty Daughter','Billy Strings'],
 ['Beaumont Rag','Tony Rice'],
 ['Senor',"Tim O'Brien"],
 ['Here Comes the Sun','The Beatles'],
 ['Walk on Boy','Doc Watson'],
 ['Ripple','Grateful Dead'],
 ['Althea','Grateful Dead'],
 ['Sugar Magnolia','Grateful Dead'],
 ['Frosty Morn','Doc Watson'],
 ['Black Mountain Rag','Billy Strings'],
 ['Never Going Back Again','Fleetwood Mac']
];
const normalizeSong=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const songKey=(title,artist)=>normalizeSong(title)+'-'+normalizeSong(artist);
function makeDefaultSong([title,artist]){return{id:'default-'+songKey(title,artist),title,artist,bpm:null,minutes:10,lesson:'',notes:'',sample:false,defaultSong:true};}
function migrateDefaults(state){if(state.defaultsRevision>=2)return state;const oldSamples=new Set([songKey('Blackbird','The Beatles'),songKey('Dust in the Wind','Kansas'),songKey('Wish You Were Here','Pink Floyd'),songKey('Landslide','Fleetwood Mac')]);state.songs=state.songs.filter(s=>{if(!s.sample||!oldSamples.has(songKey(s.title,s.artist)))return true;const used=Object.values(state.logs).some(log=>(log[s.id]||0)>0)||state.schedule.some(day=>day.some(p=>p.songId===s.id))||state.active?.songId===s.id||!!s.notes?.trim();if(used)s.sample=false;return used;});for(const entry of DEFAULT_SONGS){const key=songKey(...entry);if(!state.songs.some(s=>songKey(s.title,s.artist)===key))state.songs.push(makeDefaultSong(entry));}state.defaultsRevision=2;return state;}
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
function dayKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
const weekDay=(date=new Date())=>(date.getDay()+6)%7;
function monday(date=new Date()){const d=new Date(date);d.setHours(0,0,0,0);d.setDate(d.getDate()-weekDay(d));return d;}
function freshState(){return{version:1,defaultsRevision:2,songs:DEFAULT_SONGS.map(makeDefaultSong),schedule:Array.from({length:7},()=>[]),scheduleEnabled:false,logs:{},active:null};}
function secondsFor(state,id,key=dayKey()){return Number(state.logs[key]?.[id])||0;}
function targetFor(state,id,date=new Date()){const shared=state.sharedPractice?.songs?.find(p=>p.songId===id);if(shared)return shared.minutes*60;return state.scheduleEnabled?state.schedule[weekDay(date)].filter(p=>p.songId===id).reduce((n,p)=>n+p.minutes*60,0):0;}
function todayQueue(state,date=new Date()){return state.scheduleEnabled?state.schedule[weekDay(date)].filter(p=>state.songs.some(s=>s.id===p.songId)).map(p=>({...p,song:state.songs.find(s=>s.id===p.songId),seconds:secondsFor(state,p.songId,dayKey(date))})):[];}
function splitTime(start,end){const result=[];let cursor=start;while(cursor<end){const d=new Date(cursor),next=new Date(d);next.setHours(24,0,0,0);const until=Math.min(end,next.getTime());result.push({date:dayKey(d),seconds:(until-cursor)/1000});cursor=until;}return result;}
function dailyTarget(state,id,date=new Date()){return targetFor(state,id,date)||(state.songs.find(s=>s.id===id)?.minutes||10)*60;}
function accrue(state,now=Date.now()){const a=state.active;if(!a||!a.running)return null;const elapsed=Math.max(0,now-a.lastAt);if(!elapsed)return null;for(const part of splitTime(a.lastAt,now)){queueSharedPractice(state,a,part);state.logs[part.date]??={};state.logs[part.date][a.songId]=(state.logs[part.date][a.songId]||0)+part.seconds;}a.elapsedMs+=elapsed;a.lastAt=now;const date=dayKey(new Date(now)),goal=dailyTarget(state,a.songId,new Date(now));if(secondsFor(state,a.songId,date)>=goal&&a.goalNotified!==date){a.goalNotified=date;return{songId:a.songId,date,goalReached:true};}return null;}

function youtubeId(input){if(!input?.trim())return '';const text=input.trim();if(/^[\w-]{11}$/.test(text))return text;try{const u=new URL(text);if(!['www.youtube.com','youtube.com','m.youtube.com','youtu.be','www.youtu.be','www.youtube-nocookie.com','youtube-nocookie.com'].includes(u.hostname.toLowerCase()))return null;const id=u.hostname.endsWith('youtu.be')?u.pathname.split('/')[1]:u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts|live)\/([\w-]+)/)?.[1];return /^[\w-]{11}$/.test(id||'')?id:null;}catch{return null;}}
function validateState(s){if(!s||s.version!==1||!Array.isArray(s.songs)||s.songs.length>1000||!Array.isArray(s.schedule)||s.schedule.length!==7||!s.logs||typeof s.logs!=='object'||Array.isArray(s.logs))throw Error('This is not a valid repertoire backup.');const ids=new Set();for(const song of s.songs){if(typeof song.id!=='string'||!song.id||ids.has(song.id)||typeof song.title!=='string'||!song.title.trim()||song.title.length>200||typeof song.artist!=='string'||typeof song.notes!=='string'||(song.bpm!==null&&(!Number.isFinite(song.bpm)||song.bpm<20||song.bpm>300))||!Number.isFinite(song.minutes)||song.minutes<1||song.minutes>180||youtubeId(song.lesson)===null)throw Error('A song in this backup is invalid.');ids.add(song.id);}for(const day of s.schedule){if(!Array.isArray(day)||day.length>1000)throw Error('Invalid weekly schedule.');const used=new Set();for(const p of day){if(!ids.has(p.songId)||used.has(p.songId)||!Number.isFinite(p.minutes)||p.minutes<1||p.minutes>180)throw Error('Invalid schedule entry.');used.add(p.songId);}}for(const[key,logs]of Object.entries(s.logs)){if(!/^\d{4}-\d{2}-\d{2}$/.test(key)||!logs||typeof logs!=='object'||Array.isArray(logs))throw Error('Invalid practice history.');for(const value of Object.values(logs))if(!Number.isFinite(value)||value<0||value>86400)throw Error('Invalid practice duration.');}return s;}


class Metronome{
 constructor(onBeat=()=>{}){this.onBeat=onBeat;this.bpm=80;this.beats=4;this.step=2;this.bars=4;this.target=120;this.ramp=false;this.running=false;this.timers=[];}
 async start(){if(this.running)return;this.ctx??=new (window.AudioContext||window.webkitAudioContext)();await this.ctx.resume();this.running=true;this.beat=0;this.barCount=0;this.next=this.ctx.currentTime+.06;this.scheduler=setInterval(()=>this.schedule(),25);this.schedule();}
 schedule(){if(!this.running)return;while(this.next<this.ctx.currentTime+.1){if(this.next<this.ctx.currentTime-.1)this.next=this.ctx.currentTime+.03;const beat=this.beat,bpm=this.bpm,when=this.next,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.frequency.value=beat===0?1100:750;g.gain.setValueAtTime(0,when);g.gain.linearRampToValueAtTime(.2,when+.002);g.gain.exponentialRampToValueAtTime(.001,when+.045);o.connect(g).connect(this.ctx.destination);o.start(when);o.stop(when+.05);const timer=setTimeout(()=>{this.timers=this.timers.filter(t=>t!==timer);if(this.running)this.onBeat(beat,bpm);},Math.max(0,(when-this.ctx.currentTime)*1000));this.timers.push(timer);this.next+=60/this.bpm;this.beat=(this.beat+1)%this.beats;if(this.beat===0&&++this.barCount>=this.bars){this.barCount=0;if(this.ramp)this.bpm=Math.min(this.target,this.bpm+this.step);}}}
 stop(){this.running=false;clearInterval(this.scheduler);this.timers.forEach(clearTimeout);this.timers=[];if(this.ctx?.state==='running')this.ctx.suspend();this.onBeat(-1,this.bpm);}
}

const socialEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const socialTime=seconds=>seconds==null?'Not sharing':`${Math.floor(Number(seconds)/3600)?Math.floor(Number(seconds)/3600)+':':''}${Math.floor(Number(seconds)/3600)?String(Math.floor(Number(seconds)%3600/60)).padStart(2,'0'):Math.floor(Number(seconds)/60)}:${String(Math.floor(Number(seconds)%60)).padStart(2,'0')}`;
const socialDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
class FriendsController{
 constructor(hooks){this.hooks=hooks;this.status='loading';this.error='';this.user=null;this.profile=null;this.data={profiles:[],friendships:[],sets:[],members:[],songs:[],times:[]};this.dialog=document.createElement('dialog');this.dialog.id='socialDialog';document.body.append(this.dialog);document.addEventListener('click',event=>{const b=event.target.closest('[data-social]');if(b){event.preventDefault();this.action(b).catch(e=>this.fail(e));}});document.addEventListener('submit',event=>{if(event.target.id.startsWith('socialForm')){event.preventDefault();this.submit(event.target).catch(e=>this.fail(e));}});this.init();this.uploadInterval=setInterval(()=>this.flush().catch(e=>this.syncError(e)),10000);this.refreshInterval=setInterval(()=>{if(this.user&&document.visibilityState==='visible')this.refresh().catch(e=>this.syncError(e));},30000);}
 emit(){this.hooks.onChange();}
 fail(error){this.error=error.message||'Request failed.';this.hooks.notify(this.error);if(this.dialog.open){let p=this.dialog.querySelector('.social-error');if(!p){p=document.createElement('p');p.className='social-error';p.setAttribute('role','status');this.dialog.append(p);}p.textContent=this.error;}this.emit();}
 syncError(error){this.error='Sync failed. Saved practice will retry automatically.';this.emit();}
 async query(request){const{data,error}=await request;if(error)throw Error(error.message);return data;}
 async init(){try{this.pendingInvite=new URLSearchParams(location.search).get('set')||'';if(this.pendingInvite){try{localStorage.setItem('repertoire.pendingInvite',this.pendingInvite);}catch{}}else{try{this.pendingInvite=localStorage.getItem('repertoire.pendingInvite')||'';}catch{}}const response=await fetch(new URL('./social-config.json',location.href),{cache:'no-store'});if(!response.ok)throw Error('Shared practice is not configured.');const config=await response.json();if(!config.supabaseUrl||!config.supabasePublishableKey){this.status='unconfigured';this.emit();return;}if(!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(config.supabaseUrl))throw Error('Invalid shared-practice configuration.');const{createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');this.client=createClient(config.supabaseUrl,config.supabasePublishableKey);this.client.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>this.loadUser(session?.user||null).catch(e=>this.fail(e)),0);});const{data,error}=await this.client.auth.getSession();if(error)throw error;await this.loadUser(data.session?.user||null);}catch(error){this.status='unconfigured';this.error=error.message;this.emit();}}
 async loadUser(user){if(this.loadingUser)return;this.loadingUser=true;try{this.user=user;this.profile=null;const state=this.hooks.state();state.sharingAccount=null;if(!user){this.status='signedout';this.data={profiles:[],friendships:[],sets:[],members:[],songs:[],times:[]};this.hooks.persist();this.emit();return;}const profiles=await this.query(this.client.from('repertoire_profiles').select('id,display_name,friend_code,share_practice').eq('id',user.id));this.profile=profiles[0]||null;if(!this.profile){let name=user.user_metadata?.display_name||'';if(!name)try{name=localStorage.getItem('repertoire.displayName')||'';}catch{}if(name.trim()){this.profile=await this.query(this.client.from('repertoire_profiles').insert({id:user.id,display_name:name.trim().slice(0,60)}).select('id,display_name,friend_code,share_practice').single());}else{this.status='profile';this.emit();return;}}this.status='ready';state.sharingAccount=this.profile.share_practice?user.id:null;this.hooks.persist();await this.flush();await this.refresh();}finally{this.loadingUser=false;}}
 async all(table,filter){const rows=[];for(let from=0;from<50000;from+=1000){let q=this.client.from(table).select('*').range(from,from+999);if(filter)q=filter(q);const batch=await this.query(q);rows.push(...batch);if(batch.length<1000)return rows;}throw Error('Too many practice records to display.');}
 async refresh(){if(!this.user||!this.profile||this.refreshing)return;this.refreshing=true;try{const[profiles,friendships,sets,members,songs,times]=await Promise.all([this.all('repertoire_profiles'),this.all('repertoire_friendships'),this.all('repertoire_sets'),this.all('repertoire_set_members'),this.all('repertoire_set_songs'),this.all('repertoire_practice_sessions',q=>q.eq('practice_day',socialDate()))]);this.data={profiles,friendships,sets,members,songs,times};this.profile=profiles.find(p=>p.id===this.user.id)||this.profile;this.updated=new Date();this.error='';this.emit();if(this.openSetId&&this.dialog.open&&!document.activeElement?.closest('form'))this.renderSet(this.openSetId);}finally{this.refreshing=false;}}
 capture(){/* Practice events are durably queued by the timer; uploads run in the background. */}
 async flush(){if(!this.client||!this.user||!this.profile?.share_practice||this.syncing)return;const state=this.hooks.state(),records=(state.socialQueue||[]).filter(r=>r.accountId===this.user.id).slice(0,100).map(r=>({...r}));if(!records.length)return;this.syncing=true;try{await this.query(this.client.rpc('repertoire_sync_practice',{p_records:records}));acknowledgeSharedRecords(state,records);this.hooks.persist();}finally{this.syncing=false;}}
 person(id){return this.data.profiles.find(p=>p.id===id)||{id,display_name:'Member',share_practice:false};}
 total(id,key=null){const p=this.person(id);if(!p.share_practice)return null;return this.data.times.filter(t=>t.user_id===id&&(!key||t.song_key===key)).reduce((n,t)=>n+Number(t.seconds),0);}
 set(id){const group=this.data.sets.find(s=>s.id===id);return group?{...group,songs:this.data.songs.filter(s=>s.set_id===id).sort((a,b)=>a.position-b.position)}:null;}
 render(root){const e=socialEscape;let html='<div class="intro-row"><div class="section-title"><h1>Friends</h1><div class="section-date">'+e(new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}))+'</div></div>'+(this.status==='ready'?'<button class="secondary" data-social="refresh">Refresh</button>':'')+'</div>';if(this.status==='loading'){root.innerHTML=html+'<div class="empty">Loading account…</div>';return;}if(this.status==='unconfigured'){root.innerHTML=html+'<section class="social-panel"><h2>Shared practice</h2><p>Friends and shared sets are not connected yet. Personal practice is available in the other tabs.</p></section>';return;}if(this.status==='signedout'){const signup=this.authMode==='signup';root.innerHTML=html+'<section class="social-panel auth-panel"><h2>'+(signup?'Create account':'Sign in')+'</h2><p>Practice times are shared only when you enable sharing.</p><form id="socialFormSignIn">'+(signup?'<label class="field">Display name<input name="displayName" maxlength="60" required autocomplete="nickname"></label>':'')+'<label class="field">Email<input name="email" type="email" required autocomplete="email"></label><label class="field">Password<input name="password" type="password" minlength="8" required autocomplete="'+(signup?'new-password':'current-password')+'"></label><div class="form-actions"><button class="primary" type="submit">'+(signup?'Create account':'Sign in')+'</button><button class="text-button" type="button" data-social="auth-mode">'+(signup?'Sign in instead':'Create account')+'</button></div></form><p class="section-note">Your email address is not shown to other members.</p>'+(this.authNotice?'<p role="status">'+e(this.authNotice)+'</p>':'')+'</section>'+this.errorMarkup();return;}if(this.status==='profile'){root.innerHTML=html+'<section class="social-panel"><h2>Profile</h2><form id="socialFormProfile"><label class="field">Display name<input name="displayName" maxlength="60" required></label><div class="form-actions"><button class="primary">Save profile</button></div></form></section>'+this.errorMarkup();return;}
 const accepted=this.data.friendships.filter(f=>f.status==='accepted'),incoming=this.data.friendships.filter(f=>f.status==='pending'&&f.recipient===this.user.id),outgoing=this.data.friendships.filter(f=>f.status==='pending'&&f.requester===this.user.id),invite=this.pendingInvite||'';
 html+='<section class="social-account"><div><strong>'+e(this.profile.display_name)+'</strong><span>Friend code: <code>'+e(this.profile.friend_code)+'</code> <button class="text-button" data-social="copy-code">Copy</button></span></div><div class="social-account-actions"><label class="switch-label"><input type="checkbox" data-social="sharing" '+(this.profile.share_practice?'checked':'')+'> Share practice</label><button class="text-button" data-social="signout">Sign out</button></div><p class="section-note">When enabled, new practice time is visible to accepted friends and shared-set members. Private notes and previous local history are not uploaded.</p></section>'+this.errorMarkup();
 html+='<div class="section-heading"><h2>Friends today</h2><small>'+e(socialDate())+'</small></div><div class="friend-list">'+(accepted.length?accepted.map(f=>{const id=f.requester===this.user.id?f.recipient:f.requester,p=this.person(id);return '<div class="friend-row"><span class="person-avatar">'+e(p.display_name.slice(0,1).toUpperCase())+'</span><strong>'+e(p.display_name)+'</strong><span class="friend-time">'+socialTime(this.total(id))+'</span><button class="text-button" data-social="remove-friend" data-id="'+f.id+'">Remove</button></div>';}).join(''):'<div class="empty">No friends added.</div>')+'</div><form id="socialFormFriend" class="inline-form"><label class="visually-hidden" for="friendCode">Friend code</label><input id="friendCode" name="code" placeholder="Friend code" required maxlength="64" autocomplete="off"><button class="primary">Add friend</button></form>';
 if(incoming.length||outgoing.length)html+='<section class="social-panel"><h2>Requests</h2>'+incoming.map(f=>'<div class="request-row"><span>'+e(this.person(f.requester).display_name)+'</span><button class="primary" data-social="accept" data-id="'+f.id+'">Accept</button><button class="secondary" data-social="remove-friend" data-id="'+f.id+'">Decline</button></div>').join('')+outgoing.map(f=>'<div class="request-row"><span>'+e(this.person(f.recipient).display_name)+'</span><small>Request sent</small><button class="text-button" data-social="remove-friend" data-id="'+f.id+'">Cancel</button></div>').join('')+'</section>';
 html+='<div class="section-heading"><h2>Shared sets</h2><button class="primary" data-social="create-set">+ Create set</button></div><div class="shared-set-grid">'+(this.data.sets.length?this.data.sets.map(s=>'<button class="shared-set-card" data-social="open-set" data-id="'+s.id+'"><strong>'+e(s.name)+'</strong><span>'+this.data.songs.filter(r=>r.set_id===s.id).length+' songs · '+this.data.members.filter(m=>m.set_id===s.id).length+' members</span><small>'+(s.owner_id===this.user.id?'Owner':'Member')+'</small></button>').join(''):'<div class="empty">No shared sets.</div>')+'</div><form id="socialFormJoin" class="inline-form"><label class="visually-hidden" for="setCode">Set invite code or link</label><input id="setCode" name="code" placeholder="Set invite code or link" value="'+e(invite)+'" required maxlength="1000"><button class="secondary">Join set</button></form><p class="section-note">Times are shown for the displayed calendar date and update every 30 seconds. Only practice recorded while sharing is enabled is included.</p>';root.innerHTML=html;}
 errorMarkup(){return this.error?'<p class="social-error" role="status">'+socialEscape(this.error)+'</p>':'';}
 renderSet(id){const group=this.set(id);if(!group)return;this.openSetId=id;const e=socialEscape,members=this.data.members.filter(m=>m.set_id===id).map(m=>this.person(m.user_id));this.dialog.innerHTML='<button class="close" data-close="socialDialog" aria-label="Close shared set">×</button><h2>'+e(group.name)+'</h2><div class="set-toolbar"><button class="primary" data-social="practice-set" data-id="'+id+'">Practice set</button><button class="secondary" data-social="copy-invite" data-id="'+id+'">Copy invite link</button>'+(group.owner_id===this.user.id?'<button class="secondary" data-social="edit-set" data-id="'+id+'">Edit set</button>':'<button class="text-button" data-social="leave-set" data-id="'+id+'">Leave set</button>')+'</div><div class="section-heading"><h3>Practice today</h3><small>'+e(socialDate())+'</small></div><div class="set-matrix-wrap"><table class="set-matrix"><thead><tr><th>Song / target</th>'+members.map(p=>'<th>'+e(p.display_name)+(p.id===this.user.id?' (you)':'')+'</th>').join('')+'</tr></thead><tbody>'+group.songs.map(s=>'<tr><th>'+e(s.title)+'<small>'+e(s.artist)+' · '+s.minutes+' min</small></th>'+members.map(p=>{const sec=this.total(p.id,s.song_key),progress=sec==null?0:Math.min(sec/(s.minutes*60),1);return '<td><strong>'+socialTime(sec)+'</strong><div class="member-progress"><i style="width:'+Math.round(progress*100)+'%"></i></div></td>';}).join('')+'</tr>').join('')+'<tr><th>Set total</th>'+members.map(p=>'<td><strong>'+socialTime(p.share_practice?group.songs.reduce((n,s)=>n+(this.total(p.id,s.song_key)||0),0):null)+'</strong></td>').join('')+'</tr></tbody></table></div><p class="section-note">All shared practice on these songs counts, including sessions outside this set. Invite links allow any signed-in person with the link to join.</p>'+(group.owner_id===this.user.id?'<button class="danger" data-social="delete-set" data-id="'+id+'">Delete set</button>':'');if(!this.dialog.open)this.dialog.showModal();}
 editSet(id=null){const group=id?this.set(id):null;this.openSetId=null;const e=socialEscape,songs=this.hooks.state().songs,byKey=new Map();for(const song of songs)byKey.set(canonicalSong(song.title,song.artist),song);if(group)for(const song of group.songs)if(!byKey.has(song.song_key))byKey.set(song.song_key,{id:song.song_key,title:song.title,artist:song.artist,bpm:song.bpm,minutes:song.minutes});this.editSongs=[...byKey.values()];this.dialog.innerHTML='<button class="close" data-close="socialDialog" aria-label="Close set editor">×</button><h2>'+(group?'Edit shared set':'Create shared set')+'</h2><form id="socialFormSet" data-set-id="'+e(id||'')+'"><label class="field">Set name<input name="name" maxlength="100" value="'+e(group?.name||'')+'" required></label><div class="set-song-picker">'+this.editSongs.map((s,i)=>{const current=group?.songs.find(item=>item.song_key===canonicalSong(s.title,s.artist));return '<label class="set-pick-row"><input type="checkbox" name="song" value="'+i+'" '+(current?'checked':'')+'><span>'+e(s.title)+'<small>'+e(s.artist)+'</small></span><input type="number" min="1" max="180" value="'+(current?.minutes||s.minutes||10)+'" data-song-minutes="'+i+'" aria-label="Target minutes for '+e(s.title)+'"><small>min</small></label>';}).join('')+'</div><div class="form-actions"><button type="button" class="secondary" data-close="socialDialog">Cancel</button><button class="primary">Save set</button></div></form>';if(!this.dialog.open)this.dialog.showModal();}
 async copy(text){try{await navigator.clipboard.writeText(text);this.hooks.notify('Copied.');}catch{this.dialog.innerHTML='<button class="close" data-close="socialDialog" aria-label="Close">×</button><h2>Copy invitation</h2><input readonly value="'+socialEscape(text)+'" aria-label="Invitation">';if(!this.dialog.open)this.dialog.showModal();this.dialog.querySelector('input').select();}}
 async action(button){if(button.disabled)return;const action=button.dataset.social,id=button.dataset.id;button.disabled=true;try{switch(action){case'auth-mode':this.authMode=this.authMode==='signup'?'signin':'signup';this.error='';this.authNotice='';this.emit();break;case'refresh':await this.flush();await this.refresh();break;case'copy-code':await this.copy(this.profile.friend_code);break;case'signout':await this.flush();await this.client.auth.signOut();await this.loadUser(null);break;case'sharing':this.hooks.beforeSharing();this.profile=await this.query(this.client.from('repertoire_profiles').update({share_practice:button.checked}).eq('id',this.user.id).select('id,display_name,friend_code,share_practice').single());this.hooks.state().sharingAccount=this.profile.share_practice?this.user.id:null;this.hooks.persist();await this.refresh();break;case'accept':await this.query(this.client.rpc('repertoire_accept_friend',{p_request:id}));await this.refresh();break;case'remove-friend':await this.query(this.client.from('repertoire_friendships').delete().eq('id',id));await this.refresh();break;case'create-set':this.editSet();break;case'edit-set':this.editSet(id);break;case'open-set':this.renderSet(id);break;case'copy-invite':await this.copy(new URL('./?set='+this.set(id).invite_code+'&view=friends',location.href).href);break;case'practice-set':{const group=this.set(id);this.dialog.close();this.openSetId=null;this.hooks.practiceSet(group);break;}case'leave-set':if(!confirm('Leave this shared set? Your recorded practice remains saved.'))break;await this.query(this.client.rpc('repertoire_leave_set',{p_set:id}));this.dialog.close();this.openSetId=null;await this.refresh();break;case'delete-set':if(!confirm('Delete this set for all members? Practice history will remain saved.'))break;await this.query(this.client.from('repertoire_sets').delete().eq('id',id));this.dialog.close();this.openSetId=null;await this.refresh();break;}}finally{button.disabled=false;}}
 async submit(form){const button=form.querySelector('button[type=submit]')||form.querySelector('button.primary');if(button)button.disabled=true;try{const data=new FormData(form);switch(form.id){case'socialFormSignIn':{const email=String(data.get('email')).trim(),password=String(data.get('password'));this.error='';this.authNotice='';if(this.authMode==='signup'){const name=String(data.get('displayName')||'').trim();if(!name)throw Error('Enter your display name.');if(password.length<8)throw Error('Use at least 8 characters for your password.');const result=await this.query(this.client.auth.signUp({email,password,options:{data:{display_name:name},emailRedirectTo:new URL('./?view=friends',location.href).href}}));if(result.session){await this.loadUser(result.session.user);}else{form.reset();this.authNotice='Check your email to confirm your account before signing in.';this.authMode='signin';this.emit();}}else{const result=await this.query(this.client.auth.signInWithPassword({email,password}));await this.loadUser(result.user);}break;}case'socialFormProfile':{const name=String(data.get('displayName')).trim();if(!name)throw Error('Enter your display name.');await this.query(this.client.from('repertoire_profiles').insert({id:this.user.id,display_name:name.slice(0,60)}));try{localStorage.setItem('repertoire.displayName',name);}catch{}this.loadingUser=false;await this.loadUser(this.user);break;}case'socialFormFriend':await this.query(this.client.rpc('repertoire_request_friend',{p_code:String(data.get('code')).trim()}));await this.refresh();this.hooks.notify('Friend request sent.');break;case'socialFormJoin':{let code=String(data.get('code')).trim();try{code=new URL(code).searchParams.get('set')||code;}catch{}const id=await this.query(this.client.rpc('repertoire_join_set',{p_code:code}));this.pendingInvite='';try{localStorage.removeItem('repertoire.pendingInvite');}catch{}await this.refresh();this.renderSet(id);break;}case'socialFormSet':{const indices=data.getAll('song').map(Number);if(!indices.length||indices.length>100)throw Error('Choose between 1 and 100 songs.');const songs=indices.map(i=>{const s=this.editSongs[i],minutes=Number(form.querySelector('[data-song-minutes="'+i+'"]').value);if(!s||!Number.isInteger(minutes)||minutes<1||minutes>180)throw Error('Use targets between 1 and 180 minutes.');return{song_key:canonicalSong(s.title,s.artist),title:s.title,artist:s.artist,bpm:s.bpm,minutes};}),name=String(data.get('name')).trim();if(!name)throw Error('Enter a set name.');let id=form.dataset.setId;if(id)await this.query(this.client.rpc('repertoire_edit_set',{p_set:id,p_name:name,p_songs:songs}));else id=await this.query(this.client.rpc('repertoire_create_set',{p_name:name,p_songs:songs}));await this.refresh();this.renderSet(id);break;}}}finally{if(button)button.disabled=false;}}
}


function tempoLabel(song){return song.bpm==null?'BPM not set':song.bpm+' BPM';}
function progressText(seconds,goalMinutes){return seconds>0&&seconds<60?`${Math.floor(seconds)} sec / ${goalMinutes} min`:`${Math.floor(seconds/60)} / ${goalMinutes} min`;}
function metroMarkup(s){return `<div class="metronome"><div class="metro-top"><div class="bpm-display"><span id="metroBpmValue">${metro.bpm}</span><small>BPM</small></div><button class="primary" data-action="metro-play" id="metroPlay">${metro.running?'■ Stop':'▶ Start'}</button></div><div class="metro-dots">${Array.from({length:metro.beats},()=>'<span class="metro-dot"></span>').join('')}</div><div class="metro-controls"><button data-action="metro-minus" aria-label="Decrease tempo by 5">−</button><input id="metroBpm" type="number" min="20" max="300" value="${metro.bpm}" aria-label="Metronome tempo"><button data-action="metro-plus" aria-label="Increase tempo by 5">+</button><select id="metroBeats" aria-label="Beats per bar">${[2,3,4,6].map(n=>`<option value="${n}" ${metro.beats===n?'selected':''}>${n} beats / bar</option>`).join('')}</select></div><div class="ramp-options"><label><input id="rampEnabled" type="checkbox" ${metro.ramp?'checked':''}> Gradually increase the tempo</label><div class="ramp-fields">Add <input id="rampStep" type="number" min="1" max="20" value="${metro.step}" aria-label="Tempo increase in BPM"> BPM every <input id="rampBars" type="number" min="1" max="32" value="${metro.bars}" aria-label="Bars between tempo increases"> bars, up to <input id="rampTarget" type="number" min="20" max="300" value="${metro.target}" aria-label="Target tempo"> BPM.</div></div><p class="metro-note">Song tempo: ${tempoLabel(s)}. Changing songs or closing this card stops the click.</p></div>`;}
function saveMetro(){const s=songBy(selectedId);if(s){s.metro={bpm:metro.bpm,beats:metro.beats,step:metro.step,bars:metro.bars,target:metro.target,ramp:metro.ramp};save();}}
function initMetro(){const s=songBy(selectedId),m=s.metro||{};metro.bpm=Math.max(20,Math.min(300,Number(m.bpm)||(s.bpm?Math.round(s.bpm*.65):80)));metro.beats=[2,3,4,6].includes(m.beats)?m.beats:4;metro.step=Math.max(1,Math.min(20,Number(m.step)||2));metro.bars=Math.max(1,Math.min(32,Number(m.bars)||4));metro.target=Math.max(metro.bpm,Math.min(300,Number(m.target)||s.bpm||120));metro.ramp=!!m.ramp;}
function openEdit(id=null){const s=id?songBy(id):null;$('editDialog').innerHTML=`<button class="close" data-close="editDialog" aria-label="Close song editor">×</button><h2>${s?'Edit song':'Add song'}</h2><form id="songForm" data-edit-id="${e(s?.id||'')}"><label class="field">Song title<input name="title" required maxlength="200" value="${e(s?.title||'')}" placeholder="e.g. Blackbird"></label><label class="field">Artist<input name="artist" maxlength="200" value="${e(s?.artist||'')}" placeholder="e.g. The Beatles"></label><div class="form-row"><label class="field">Song tempo · BPM<input name="bpm" required type="number" min="20" max="300" step="1" value="${s?.bpm||80}"></label><label class="field">Default practice · minutes<input name="minutes" required type="number" min="1" max="180" step="1" value="${s?.minutes||10}"></label></div><label class="field">YouTube lesson<input name="lesson" type="text" maxlength="1000" value="${e(s?.lesson||'')}" placeholder="Paste a YouTube video link"><small>A regular, short, or embed video URL. Leave blank to add one later.</small></label><label class="field">Practice notes<textarea name="notes" maxlength="10000" placeholder="Practice notes">${e(s?.notes||'')}</textarea></label><div class="form-actions">${s?`<button type="button" class="danger" data-action="delete-song" data-id="${e(s.id)}">Remove song</button>`:''}<button type="button" class="secondary" data-close="editDialog">Cancel</button><button type="submit" class="primary">${s?'Save song':'Add to repertoire'} ↗</button></div></form>`;$('editDialog').showModal();}
function exportData(){finishTick();save();const blob=new Blob([JSON.stringify({...state,active:null},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`repertoire-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported.');}
async function importData(file){if(!file)return;try{if(file.size>8*1024*1024)throw Error('This backup is too large.');const next=validateState(JSON.parse(await file.text()));if(!confirm('Replace this browser’s songs, schedule, and history with this backup? Export your current journal first if you want to keep it.'))return;metro.stop();releaseWake();state=migrateDefaults({...next,active:null,sharingAccount:social?.profile?.share_practice?social.user.id:null});save();selectedId=null;$('songDialog').close();render();toast('Backup imported.');}catch(err){toast(err.message||'Could not import this backup.');}}
function stopDetail(){metro.stop();showMetro=false;selectedId=null;$('songDialog').innerHTML='';}
function startPractice(id,fromQueue=false){const s=songBy(id);if(!s)return;unlockAudio();if(state.active){if(state.active.songId===id){openPractice();return;}if(!confirm('Save the current session and start '+s.title+'?'))return;accrue(state);state.active=null;}const goal=dailyTarget(state,id),done=secondsFor(state,id);state.active={songId:id,targetSeconds:goal,elapsedMs:0,lastAt:Date.now(),running:true,goalNotified:done>=goal?dayKey():null};state.lastCompleted=null;save();render();openPractice();requestWake();}
let wakeLock;async function requestWake(){try{if('wakeLock'in navigator&&state.active?.running)wakeLock=await navigator.wakeLock.request('screen');}catch{}}
function releaseWake(){wakeLock?.release().catch(()=>{});wakeLock=null;}
function finishTick(){const reached=accrue(state);if(reached){save();chime();toast('Daily target reached. Timer is still running.');return true;}return false;}
function updateTicks(){const had=!!state.active;finishTick();if(had)save();if(dayKey()!==lastDay){lastDay=dayKey();render();if(selectedId)renderSong();}updatePractice();if($('statMinutes'))$('statMinutes').textContent=time(totalDay());if($('statSongs'))$('statSongs').textContent=state.songs.filter(s=>secondsFor(state,s.id)>0).length+' / '+state.songs.length;if($('statStreak'))$('statStreak').textContent=streak();document.querySelectorAll('.song-row').forEach(rowEl=>{const id=rowEl.dataset.songId,sec=secondsFor(state,id),goal=dailyTarget(state,id),timeEl=rowEl.querySelector('[data-row-time]'),circle=rowEl.querySelector('.practice-circle');if(timeEl)timeEl.textContent=time(sec)+' / '+goal/60+' min';if(circle){circle.setAttribute('aria-label','Practice '+songBy(id).title+'; '+duration(sec)+' today');const ring=circle.querySelector('circle');if(ring)ring.setAttribute('stroke-dashoffset',String(100.531*(1-Math.min(sec/goal,1))));circle.classList.toggle('running',state.active?.songId===id);}});if(selectedId)updateDetailStats();}
function openSong(id){if(!songBy(id))return;if(selectedId!==id){metro.stop();showMetro=false;}selectedId=id;month=new Date(new Date().getFullYear(),new Date().getMonth(),1);renderSong();if(!$('songDialog').open)$('songDialog').showModal();}
function calendar(s){const first=(month.getDay()+6)%7,count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();return `<div class="month-head"><button class="icon-button" data-action="prev-month" aria-label="Previous month">‹</button><strong>${month.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</strong><button class="icon-button" data-action="next-month" aria-label="Next month">›</button></div><div class="calendar">${DAYS.map(d=>`<div class="weekday">${d.slice(0,1)}</div>`).join('')}${'<div></div>'.repeat(first)}${Array.from({length:count},(_,i)=>{const d=new Date(month.getFullYear(),month.getMonth(),i+1),key=dayKey(d),sec=secondsFor(state,s.id,key),future=key>dayKey();return `<button class="calendar-day ${sec>0?'practiced':''} ${key===dayKey()?'today':''} ${future?'future':''}" data-action="calendar-day" data-date="${key}" aria-label="${e(d.toLocaleDateString(undefined,{month:'long',day:'numeric'}))}: ${sec>0?duration(sec)+' practiced':'No practice recorded'}" title="${sec>0?duration(sec)+' practiced':'No practice recorded'}">${i+1}${sec>0?'<small>'+duration(sec)+'</small>':''}</button>`;}).join('')}</div><div class="calendar-legend"><span><b></b> Practiced</span><span><b></b> No practice recorded</span><span>Local calendar days</span></div>`;}
function renderSong(){const s=songBy(selectedId);if(!s)return;const id=youtubeId(s.lesson);$('songDialog').innerHTML=`<button class="close" data-close="songDialog" aria-label="Close song details">×</button><div class="detail-top"><h2>${e(s.title)}</h2><div class="detail-artist">${e(s.artist||'')} <span class="mini-tag">${tempoLabel(s)}</span></div></div><div class="detail-stats"><div><strong id="detailToday">${duration(secondsFor(state,s.id))}</strong><small>TODAY</small></div><div><strong id="detailTotal">${duration(totalSong(s.id))}</strong><small>TOTAL PRACTICE</small></div><div><strong id="detailDays">${practiceDays(s.id)}</strong><small>DAYS PLAYED</small></div></div><div class="detail-actions"><button class="primary" data-action="practice" data-id="${e(s.id)}">▶ ${state.active?.songId===s.id?'View current timer':`Practice · ${s.minutes} min`}</button><button class="secondary" data-action="edit-song" data-id="${e(s.id)}">Edit song</button><button class="secondary" data-action="toggle-metro">${showMetro?'Hide':'♪ Open'} metronome</button></div><div id="metroPanel">${showMetro?metroMarkup(s):''}</div><div class="detail-section-label">Practice history</div>${calendar(s)}<div class="detail-section-label">YOUR LESSON ${id?`<a class="text-button" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">Open on YouTube ↗</a>`:''}</div>${id?`<iframe class="lesson-frame" src="https://www.youtube-nocookie.com/embed/${id}" title="YouTube lesson for ${e(s.title)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`:'<div class="lesson-placeholder">No lesson added. Add a YouTube link in Edit song.</div>'}<div class="detail-section-label"><label for="songNotes">Practice notes</label></div><textarea class="notes" id="songNotes" maxlength="10000" placeholder="Practice notes">${e(s.notes)}</textarea><div class="section-note" id="notesSaved">Notes save automatically.</div>`;}
function updateDetailStats(){const s=songBy(selectedId);if(!s)return;const seconds=secondsFor(state,s.id);if($('detailToday'))$('detailToday').textContent=duration(seconds);if($('detailTotal'))$('detailTotal').textContent=duration(totalSong(s.id));if($('detailDays'))$('detailDays').textContent=practiceDays(s.id);const todayButton=[...$('songDialog').querySelectorAll('[data-date]')].find(b=>b.dataset.date===dayKey());if(todayButton&&seconds>0){todayButton.classList.add('practiced');todayButton.innerHTML=new Date().getDate()+'<small>'+duration(seconds)+'</small>';todayButton.setAttribute('aria-label',new Date().toLocaleDateString(undefined,{month:'long',day:'numeric'})+': '+duration(seconds)+' practiced');todayButton.title=duration(seconds)+' practiced';}}
const $=id=>document.getElementById(id),PREVIEW=new URLSearchParams(location.search).get('preview')==='1',KEY='repertoire.journal.v1'+(PREVIEW?'.preview':''),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let social;
let state,view=(new URLSearchParams(location.search).get('view')==='friends'||new URLSearchParams(location.search).has('set'))?'friends':'today',search='',selectedId=null,month=new Date(new Date().getFullYear(),new Date().getMonth(),1),showMetro=false,queueMode=false,toastTimeout,lastDay=dayKey(),audio,storageFailed=false;
try{const stored=localStorage.getItem(KEY);state=stored?validateState(JSON.parse(stored)):freshState();}catch{state=freshState();setTimeout(()=>toast('Could not read browser storage. Import a backup if you have one.'),1000);}
migrateDefaults(state);
if(state.active&&(!state.songs.some(s=>s.id===state.active.songId)||!Number.isFinite(state.active.lastAt)||!Number.isFinite(state.active.elapsedMs)||!Number.isFinite(state.active.targetSeconds)||state.active.targetSeconds<=0))state.active=null;
for(const song of state.songs)if(song.sample&&!song.lesson&&STARTER_LESSONS[song.title])song.lesson=STARTER_LESSONS[song.title];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;}catch{if(!storageFailed)toast('Storage is full or unavailable. Export your journal to keep this session.');storageFailed=true;}}
function toast(text){clearTimeout(toastTimeout);$('toast').textContent=text;$('toast').classList.add('show');toastTimeout=setTimeout(()=>$('toast').classList.remove('show'),5500);}
const songBy=id=>state.songs.find(s=>s.id===id),minutes=s=>Math.floor(s/60),time=s=>`${String(Math.floor(Math.max(0,s)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,'0')}`,duration=s=>s<60?`${Math.floor(s)} sec`:`${Math.floor(s/60)} min${Math.floor(s%60)?' '+Math.floor(s%60)+' sec':''}`;
function totalDay(key=dayKey()){return Object.values(state.logs[key]||{}).reduce((a,b)=>a+b,0);}
function practiceDays(id){return Object.entries(state.logs).filter(([,logs])=>(logs[id]||0)>0).length;}
function totalSong(id){return Object.values(state.logs).reduce((n,logs)=>n+(logs[id]||0),0);}
function streak(){let n=0,d=new Date();if(totalDay(dayKey(d))<=0)d.setDate(d.getDate()-1);for(let i=0;i<36500;i++){if(totalDay(dayKey(d))<=0)break;n++;d.setDate(d.getDate()-1);}return n;}
function chime(){try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();[523.25,659.25,783.99].forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.17;o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.13,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.9);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+1);});}catch{}}
function unlockAudio(){try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();}catch{}}
const metro=new Metronome((beat,bpm)=>{document.querySelectorAll('.metro-dot').forEach((d,i)=>d.classList.toggle('lit',beat===i));if($('metroBpmValue'))$('metroBpmValue').textContent=bpm;if($('metroBpm')&&document.activeElement!==$('metroBpm'))$('metroBpm').value=bpm;});
$('songDialog').addEventListener('close',stopDetail);$('songDialog').addEventListener('cancel',()=>metro.stop());
$('backupButton').onclick=exportData;$('importFile').onchange=event=>{importData(event.target.files[0]);event.target.value='';};$('helpButton').onclick=()=>$('infoDialog').showModal();
function syncTheme(){const dark=document.documentElement.dataset.theme==='dark';$('themeToggle').innerHTML=dark?'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 14A9 9 0 0 1 10 3.5 9 9 0 1 0 20.5 14Z"/></svg>';$('themeToggle').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');$('themeToggle').setAttribute('aria-pressed',String(dark));document.querySelector('meta[name="theme-color"]').content=dark?'#141a17':'#f6f5ef';}
$('themeToggle').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('repertoire.theme',document.documentElement.dataset.theme);}catch{}syncTheme();};syncTheme();
document.addEventListener('click',async event=>{const close=event.target.closest('[data-close]');if(close){$(close.dataset.close).close();return;}const nav=event.target.closest('[data-view]');if(nav){if(nav.dataset.view==='today'&&state.sharedPractice){state.sharedPractice=null;save();}view=nav.dataset.view;search='';render();return;}const b=event.target.closest('[data-action]');if(!b)return;const{id,action,day}=b.dataset;switch(action){
case'exit-shared-set':state.sharedPractice=null;save();render();break;
case'view-today':case'view-songs':case'view-schedule':view=action.slice(5);render();break;
case'add-song':openEdit();break;case'open-song':openSong(id);break;case'edit-song':openEdit(id);break;
case'practice':if($('songDialog').open)$('songDialog').close();startPractice(id);break;

case'practice-details':$('practiceDialog').close();openSong(id);break;
case'start-next':{const p=nextPlan();if(p)startPractice(p.songId,true);break;}
case'toggle-timer':if(state.active){finishTick();if(state.active){state.active.running=!state.active.running;state.active.lastAt=Date.now();save();if(state.active.running){unlockAudio();requestWake();}else releaseWake();render();renderPractice();}}break;
case'stop-timer':if(state.active){accrue(state);state.active=null;state.lastCompleted=null;releaseWake();save();$('practiceDialog').close();render();toast('Practice saved.');}break;
case'add-plan':{const songId=$('planSelect'+day).value;if(!songId){toast('Choose a song first.');break;}state.schedule[Number(day)].push({songId,minutes:songBy(songId).minutes});save();render();break;}
case'remove-plan':state.schedule[Number(day)]=state.schedule[Number(day)].filter(p=>p.songId!==id);save();render();break;
case'prev-month':case'next-month':month.setMonth(month.getMonth()+(action==='prev-month'?-1:1));renderSong();break;
case'calendar-day':toast(`${new Date(b.dataset.date+'T12:00:00').toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})} · ${duration(secondsFor(state,selectedId,b.dataset.date))} practiced`);break;
case'toggle-metro':if(showMetro){metro.stop();showMetro=false;}else{initMetro();showMetro=true;}$('metroPanel').innerHTML=showMetro?metroMarkup(songBy(selectedId)):'';b.textContent=showMetro?'Hide metronome':'♪ Open metronome';break;
case'metro-play':try{if(metro.running){metro.stop();saveMetro();}else{await metro.start();saveMetro();}$('metroPlay').textContent=metro.running?'■ Stop':'▶ Start';}catch{toast('Audio is unavailable in this browser. Try opening this page in Safari or Chrome.');}break;
case'metro-minus':case'metro-plus':metro.bpm=Math.max(20,Math.min(300,metro.bpm+(action==='metro-plus'?5:-5)));if(metro.target<metro.bpm)metro.target=metro.bpm;$('metroBpm').value=metro.bpm;$('metroBpmValue').textContent=metro.bpm;$('rampTarget').value=metro.target;saveMetro();break;
case'export':exportData();break;
case'delete-song':if(!confirm(`Remove ${songBy(id)?.title} and its scheduled sessions? Recorded time stays in your journal backup.`))break;if(state.active?.songId===id){accrue(state);state.active=null;releaseWake();}state.songs=state.songs.filter(s=>s.id!==id);state.schedule=state.schedule.map(d=>d.filter(p=>p.songId!==id));save();$('editDialog').close();$('songDialog').close();render();toast('Song removed from your repertoire.');break;
case'remove-samples':if(!confirm('Remove the starter songs? Your own songs and recorded practice will stay.'))break;{const ids=new Set(state.songs.filter(s=>s.sample).map(s=>s.id));if(ids.has(state.active?.songId)){accrue(state);state.active=null;releaseWake();}state.songs=state.songs.filter(s=>!s.sample);state.schedule=state.schedule.map(d=>d.filter(p=>!ids.has(p.songId)));save();render();}break;
}});
document.addEventListener('submit',event=>{if(event.target.id!=='songForm')return;event.preventDefault();const f=event.target,data=new FormData(f),lesson=String(data.get('lesson')).trim();if(youtubeId(lesson)===null){toast('Use a valid YouTube video link, or leave the lesson blank.');f.elements.lesson.focus();return;}const title=String(data.get('title')).trim();if(!title){f.elements.title.focus();return;}const id=f.dataset.editId||uid(),old=songBy(id),s={...old,id,title,artist:String(data.get('artist')).trim(),bpm:Number(data.get('bpm')),minutes:Number(data.get('minutes')),lesson,notes:String(data.get('notes')),sample:false};if(old)state.songs[state.songs.findIndex(s=>s.id===id)]=s;else state.songs.push(s);save();$('editDialog').close();render();if(selectedId===id)renderSong();toast(old?'Song updated.':'Song added.');});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='songNotes'&&selectedId){songBy(selectedId).notes=t.value;save();$('notesSaved').textContent='Saved.';}if(t.id==='songSearch'){search=t.value;const results=state.songs.filter(s=>`${s.title} ${s.artist}`.toLowerCase().includes(search.toLowerCase()));$('allSongs').innerHTML=results.length?results.map(s=>row(s)).join(''):'<div class="empty">No songs match that search.</div>';}if(t.dataset.planDay!==undefined){const value=Number(t.value),day=Number(t.dataset.planDay);if(Number.isInteger(value)&&value>=1&&value<=180){const entry=state.schedule[day].find(p=>p.songId===t.dataset.planSong);if(entry){entry.minutes=value;save();t.closest('.day-plan').querySelector('header small').textContent=state.schedule[day].reduce((n,p)=>n+p.minutes,0)+' min';document.querySelector('.week-total strong').textContent=state.schedule.flat().reduce((n,p)=>n+p.minutes,0)+' minutes';}}}});
document.addEventListener('change',event=>{const t=event.target;if(t.matches('[data-import]')){importData(t.files[0]);t.value='';}if(t.id==='scheduleEnabled'){state.scheduleEnabled=t.checked;save();render();toast(t.checked?'Schedule enabled.':'Schedule disabled.');}if(t.dataset.planDay!==undefined){const value=Number(t.value);if(!Number.isInteger(value)||value<1||value>180){toast('Choose between 1 and 180 minutes.');render();return;}state.schedule[Number(t.dataset.planDay)].find(p=>p.songId===t.dataset.planSong).minutes=value;save();render();}const metroKeys={metroBpm:['bpm',20,300],metroBeats:['beats',2,6],rampStep:['step',1,20],rampBars:['bars',1,32],rampTarget:['target',20,300]};if(metroKeys[t.id]){const[key,min,max]=metroKeys[t.id],value=Number(t.value);if(!Number.isInteger(value)||value<min||value>max){t.value=metro[key];toast(`Choose a value from ${min} to ${max}.`);return;}metro[key]=value;if(metro.target<metro.bpm)metro.target=metro.bpm;saveMetro();$('metroBpmValue').textContent=metro.bpm;$('rampTarget').value=metro.target;if(t.id==='metroBeats'){metro.beat=0;document.querySelector('.metro-dots').innerHTML=Array.from({length:metro.beats},()=>'<span class="metro-dot"></span>').join('');}}if(t.id==='rampEnabled'){metro.ramp=t.checked;if(metro.ramp&&metro.target<metro.bpm){metro.target=metro.bpm;$('rampTarget').value=metro.target;}saveMetro();}});
window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue){try{state=validateState(JSON.parse(event.newValue));render();}catch{}}});
window.addEventListener('pagehide',()=>{accrue(state);save();metro.stop();});document.addEventListener('visibilitychange',()=>{if(!document.hidden){finishTick();save();render();requestWake();}});
social=new FriendsController({state:()=>state,persist:save,notify:toast,beforeSharing:()=>{accrue(state);save();},onChange:()=>{if(view==='friends'&&(social.status!=='ready'||!document.activeElement?.closest('#main form')))social.render($('main'));},practiceSet:group=>{addSharedSet(state,group);save();view='today';render();}});
finishTick();save();render();setInterval(updateTicks,1000);if(PREVIEW)toast('Preview data is stored separately.');
function weekStrip(){const start=monday();return `<div class="day-strip" aria-label="This week's practice">${DAYS.map((day,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const total=totalDay(dayKey(d));return `<div class="day-chip ${dayKey(d)===dayKey()?'today':''} ${total>0?'done':''}" title="${e(day)}: ${duration(total)}"><span>${day.slice(0,3)}</span><strong>${d.getDate()}</strong><i></i></div>`;}).join('')}</div>`;}
function row(s,plan=null){const sec=secondsFor(state,s.id),goal=plan?plan.minutes*60:dailyTarget(state,s.id);return '<div class="song-row" data-song-id="'+e(s.id)+'"><button class="practice-circle '+(state.active?.songId===s.id?'running':'')+'" data-action="practice" data-id="'+e(s.id)+'" aria-label="Practice '+e(s.title)+'; '+duration(sec)+' today"><svg viewBox="0 0 40 40" aria-hidden="true"><circle class="row-ring-base" cx="20" cy="20" r="16"/><circle cx="20" cy="20" r="16" class="row-ring-fill" stroke-dasharray="100.531" stroke-dashoffset="'+100.531*(1-Math.min(sec/goal,1))+'"/></svg></button><button class="song-open" data-action="open-song" data-id="'+e(s.id)+'"><span class="song-title">'+e(s.title)+'</span><span class="song-artist">'+e(s.artist)+'</span></button><div class="song-meta"><strong data-row-time>'+time(sec)+' / '+goal/60+' min</strong><span>'+tempoLabel(s)+'</span></div></div>';}
function ring(percent=0,display='00:00',label='SESSION'){return '<div class="ring-wrap"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="ring-base" cx="60" cy="60" r="53"/><circle id="ringProgress" class="ring-progress" cx="60" cy="60" r="53" stroke-dasharray="333.01" stroke-dashoffset="'+333.01*(1-Math.min(1,percent))+'"/></svg><div class="ring-inner"><strong id="timerClock">'+display+'</strong><small id="timerLabel">'+label+'</small></div></div>';}
function nextPlan(){return todayQueue(state).find(p=>p.seconds+0.01<p.minutes*60);}
function timerCard(){return '';}
function openPractice(){if(!state.active)return;renderPractice();if(!$('practiceDialog').open)$('practiceDialog').showModal();}
function renderPractice(){const a=state.active,s=a?songBy(a.songId):null;if(!s){$('practiceDialog').close();return;}const today=secondsFor(state,s.id),goal=dailyTarget(state,s.id);$('practiceDialog').innerHTML='<button class="close" data-close="practiceDialog" aria-label="Close practice card">×</button><div class="practice-heading"><span>Practice</span><h2>'+e(s.title)+'</h2><p>'+e(s.artist)+' · '+tempoLabel(s)+'</p></div>'+ring(today/goal,time(a.elapsedMs/1000),'SESSION TIME')+'<div class="practice-totals"><div><strong id="practiceToday">'+time(today)+'</strong><span>Today</span></div><div><strong id="practiceTarget">'+goal/60+' min</strong><span>Daily target</span></div></div><p id="practiceStatus" class="practice-status">'+(today>=goal?'Daily target reached':a.running?'Recording practice':'Paused')+'</p><div class="practice-buttons"><button class="secondary" data-action="toggle-timer">'+(a.running?'Pause':'Resume')+'</button><button class="primary" data-action="stop-timer">Finish & save</button></div><button class="text-button" data-action="practice-details" data-id="'+e(s.id)+'">Lesson & metronome</button><p class="section-note">The timer continues beyond your target. Finish to save your final time.</p>';}
function updatePractice(){const a=state.active;if(!a)return;const sec=secondsFor(state,a.songId),goal=dailyTarget(state,a.songId);if($('timerClock'))$('timerClock').textContent=time(a.elapsedMs/1000);if($('practiceToday'))$('practiceToday').textContent=time(sec);if($('practiceTarget'))$('practiceTarget').textContent=goal/60+' min';$('ringProgress')?.setAttribute('stroke-dashoffset',String(333.01*(1-Math.min(sec/goal,1))));if($('practiceStatus'))$('practiceStatus').textContent=(a.running?'Recording practice':'Paused')+(sec>=goal?' · Target reached':'');}
function mobileBackup(){return '<div class="mobile-backup"><button data-action="export">↗ Export journal</button><label>↙ Import backup<input type="file" accept=".json,application/json" data-import></label></div>';}
function render(){const today=new Date();$('songCount').textContent=state.songs.length;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));updatePractice();if(view==='friends'){social.render($('main'));return;}if(view==='schedule'){renderSchedule();return;}const queue=state.sharedPractice?state.sharedPractice.songs.filter(p=>songBy(p.songId)).map(p=>({...p,song:songBy(p.songId),seconds:secondsFor(state,p.songId)})):todayQueue(state),ids=new Set(queue.map(p=>p.songId));let content='';if(view==='today'&&queue.length){content='<div class="section-heading"><h2>'+(state.sharedPractice?'Shared set: '+e(state.sharedPractice.name):'Scheduled today')+'</h2>'+(state.sharedPractice?'<button class="text-button" data-action="exit-shared-set">Exit set</button>':'<button class="text-button" data-action="view-schedule">Edit schedule</button>')+'</div><div class="song-list">'+queue.map(p=>row(p.song,p)).join('')+'</div>';const extra=state.songs.filter(s=>!ids.has(s.id));if(extra.length)content+='<div class="section-heading"><h2>Other songs</h2></div><div class="song-list">'+extra.map(s=>row(s)).join('')+'</div>';}else{const songs=state.songs.filter(s=>(s.title+' '+s.artist).toLowerCase().includes(search.toLowerCase()));content='<div class="search-bar"><input id="songSearch" type="search" placeholder="Search songs or artists" aria-label="Search repertoire" value="'+e(search)+'"></div><div class="song-list" id="allSongs">'+(songs.length?songs.map(s=>row(s)).join(''):'<div class="empty">No songs found.</div>')+'</div>';}const st='<div class="stats-row"><div class="stat"><strong id="statMinutes">'+time(totalDay())+'</strong><span>Today</span></div><div class="stat"><strong id="statSongs">'+state.songs.filter(s=>secondsFor(state,s.id)>0).length+' / '+state.songs.length+'</strong><span>Songs practiced</span></div><div class="stat"><strong id="statStreak">'+streak()+'</strong><span>Day streak</span></div></div>';$('main').innerHTML='<div class="intro-row"><div class="section-title"><h1>'+(view==='today'?'Practice':'Repertoire')+'</h1><div class="section-date">'+e(today.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}))+'</div></div>'+(view==='songs'?'<button class="primary" data-action="add-song">+ Add song</button>':'')+'</div>'+st+content+(state.songs.some(s=>s.sample)?'<div class="sample-note">Sample songs <button data-action="remove-samples">Remove samples</button></div>':'')+mobileBackup();}
function renderSchedule(){const total=state.schedule.flat().reduce((n,p)=>n+p.minutes,0);$('main').innerHTML=`<div class="intro-row"><div class="section-title"><h1>Schedule</h1><div class="section-date">${e(new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}))}</div></div><button class="primary" data-action="view-today">Practice ↗</button></div><div class="schedule-banner"><div><strong>${state.scheduleEnabled?'Schedule enabled':'Schedule disabled'}</strong><small>Saved automatically. Your daily queue renews each local calendar day.</small></div><label class="switch-label"><input id="scheduleEnabled" type="checkbox" ${state.scheduleEnabled?'checked':''}> Run schedule</label></div><div class="schedule-grid">${DAYS.map((day,i)=>`<section class="day-plan ${i===weekDay()?'today':''}"><header><strong>${day}${i===weekDay()?' <span class="pill">Today</span>':''}</strong><small>${state.schedule[i].reduce((n,p)=>n+p.minutes,0)} min</small></header>${state.schedule[i].length?state.schedule[i].map(p=>`<div class="plan-item"><span>${e(songBy(p.songId)?.title||'Unknown song')}</span><input type="number" min="1" max="180" step="1" value="${p.minutes}" data-plan-day="${i}" data-plan-song="${e(p.songId)}" aria-label="Minutes for ${e(songBy(p.songId)?.title)} on ${day}"><small>min</small><button class="icon-button" data-action="remove-plan" data-day="${i}" data-id="${e(p.songId)}" aria-label="Remove ${e(songBy(p.songId)?.title)} from ${day}">×</button></div>`).join(''):'<div class="rest-day">No songs scheduled.</div>'}<div class="add-plan"><select id="planSelect${i}" aria-label="Add a song to ${day}"><option value="">Choose a song…</option>${state.songs.filter(s=>!state.schedule[i].some(p=>p.songId===s.id)).map(s=>`<option value="${e(s.id)}">${e(s.title)}</option>`).join('')}</select><button class="secondary" data-action="add-plan" data-day="${i}" aria-label="Add selected song to ${day}">+</button></div></section>`).join('')}</div><p class="week-total"><strong>${total} minutes</strong> scheduled per week.</p><p class="section-note">All practice on a song counts toward that day’s goal, including extra sessions. Finish a song early and the remaining minutes stay in your queue.</p>${mobileBackup()}`;}








})();
